@Component
public class AngryProvider implements AuthenticationProvider {
    public Authentication authenticate(Authentication auth) {
        throw new BadCredentialsException("angry says no");
    }
    public boolean supports(Class<?> a) {
        return UsernamePasswordAuthenticationToken.class.isAssignableFrom(a);
    }
}

